"use client";

import { useState, useEffect } from 'react';
import { 
  Globe, 
  Code2, 
  Sparkles, 
  CheckCircle2, 
  ChevronRight, 
  ArrowLeft,
  Loader2,
  Terminal,
  Zap,
  Target,
  Wind,
  Activity,
  Layers
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { useSDGStore } from '@/services/storage/sdg-store';
import { CodeEditor } from '@/components/student/CodeEditor';
import { MergeManager } from '@/lib/MergeManager';
import { DigitalTwin } from '@/components/student/DigitalTwin';
import { firebaseService } from '@/services/firebase/firebase-service';

export default function StudentLab() {
  const { currentRoadmap, setRoadmap, studentProgress, updateProgress, unlockNextModule } = useSDGStore();
  const [activeModuleId, setActiveModuleId] = useState<string | null>(null);
  const [localCode, setLocalCode] = useState('');
  const [isVerifying, setIsVerifying] = useState(false);
  const [showMerge, setShowMerge] = useState(false);
  const [isMerging, setIsMerging] = useState(false);

  // Sync with Firebase
  useEffect(() => {
    const unsubscribe = firebaseService.subscribeToRoadmap('global-class', (roadmap) => {
      setRoadmap(roadmap);
    });
    return () => unsubscribe();
  }, [setRoadmap]);

  // Initialize first module
  useEffect(() => {
    if (currentRoadmap && currentRoadmap.modules.length > 0 && !activeModuleId) {
      setActiveModuleId(currentRoadmap.modules[0].id);
      const initialProgress = studentProgress.find(p => p.moduleId === currentRoadmap.modules[0].id);
      setLocalCode(initialProgress?.savedCode || '');
    }
  }, [currentRoadmap, activeModuleId, studentProgress]);

  // Update local code when switching modules
  useEffect(() => {
    if (activeModuleId) {
      const p = studentProgress.find(p => p.moduleId === activeModuleId);
      setLocalCode(p?.savedCode || '');
    }
  }, [activeModuleId, studentProgress]);

  const handleVerify = async () => {
    if (!activeModuleId || !currentRoadmap) return;
    setIsVerifying(true);
    
    // Simulating Snap-Logic verification (e.g., check for keyword)
    const activeMod = currentRoadmap.modules.find(m => m.id === activeModuleId);
    const isValid = localCode.includes('def') || localCode.length > 10;
    
    setTimeout(() => {
      if (isValid) {
        updateProgress(activeModuleId, 'COMPLETED', localCode);
        unlockNextModule(activeModuleId);
      }
      setIsVerifying(false);
    }, 1500);
  };

  const handleFinalMerge = () => {
    setIsMerging(true);
    setTimeout(() => {
      setShowMerge(true);
      setIsMerging(false);
    }, 3000);
  };

  const activeModule = currentRoadmap?.modules.find(m => m.id === activeModuleId);
  const completionPercentage = currentRoadmap ? 
    Math.round((studentProgress.filter(p => p.status === 'COMPLETED').length / currentRoadmap.modules.length) * 100) : 0;

  if (!currentRoadmap) {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center p-12 overflow-hidden relative">
        <div className="absolute top-0 left-0 w-full h-full bg-blue-600/5 blur-[120px] animate-pulse" />
        <div className="text-center space-y-8 relative z-10">
          <div className="w-20 h-20 bg-blue-600/10 border border-blue-500/20 rounded-3xl flex items-center justify-center mx-auto animate-bounce">
            <Zap className="w-10 h-10 text-blue-500" />
          </div>
          <div className="space-y-2">
            <h2 className="text-4xl font-black uppercase italic tracking-tighter text-white">Waiting for Manifest...</h2>
            <p className="text-[10px] font-black uppercase tracking-widest text-slate-500 leading-relaxed max-w-xs mx-auto text-center">
              Your Teacher Architect is currently synthesizing the SDG Roadmap Artifact. 
            </p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="h-screen bg-slate-950 text-white font-sans selection:bg-blue-500/30 overflow-hidden flex flex-col">
      
      {/* Dynamic Background Decor */}
      <div className="absolute top-0 right-0 w-1/2 h-screen bg-blue-600/5 blur-[120px] pointer-events-none" />

      {/* Navigation */}
      <nav className="h-20 shrink-0 px-12 flex items-center justify-between border-b border-white/5 bg-slate-950/50 backdrop-blur-xl z-20">
        <div className="flex items-center space-x-6">
          <Link href="/" className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center shadow-xl shadow-blue-500/20 hover:scale-110 transition-transform">
            <Code2 className="w-6 h-6 text-white" />
          </Link>
          <div>
            <h1 className="text-sm font-black uppercase tracking-tighter italic leading-none">{currentRoadmap.courseTitle}</h1>
            <div className="flex items-center space-x-2 mt-1">
              <span className="text-[8px] font-black uppercase text-blue-500 tracking-widest leading-none">SDG {currentRoadmap.primarySDG.id}</span>
              <div className="w-1 h-1 bg-white/20 rounded-full" />
              <span className="text-[8px] font-black uppercase text-slate-500 tracking-widest leading-none">Modular Sandbox</span>
            </div>
          </div>
        </div>

        <div className="flex items-center space-x-8">
           <div className="flex items-center space-x-3 px-4 py-2 bg-white/5 rounded-full border border-white/10">
              <Activity className="w-3 h-3 text-blue-500" />
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Sync: WebSocket Active</span>
           </div>
           <button 
             onClick={handleFinalMerge}
             disabled={completionPercentage < 100 || isMerging}
             className="relative px-6 h-10 bg-white text-slate-950 rounded-xl font-black text-[9px] uppercase tracking-widest hover:bg-blue-400 transition-all disabled:opacity-30 disabled:cursor-not-allowed group overflow-hidden"
           >
             <span className="relative z-10">{isMerging ? 'Compiling Impact...' : 'Final Merge'}</span>
             {isMerging && (
               <motion.div 
                 initial={{ x: '-100%' }}
                 animate={{ x: '100%' }}
                 transition={{ duration: 1.5, repeat: Infinity, ease: 'linear' }}
                 className="absolute inset-0 bg-blue-500/30"
               />
             )}
           </button>
        </div>
      </nav>

      <div className="flex-1 flex overflow-hidden">
        {/* Left Module Sidebar */}
        <aside className="w-80 border-r border-white/5 bg-slate-950/30 p-8 space-y-8 overflow-y-auto">
          <div className="space-y-1">
            <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-500">Modular Roadmap</h3>
            <p className="text-[8px] font-bold text-slate-500 uppercase tracking-widest">Progress: {studentProgress.filter(p => p.status === 'COMPLETED').length}/{currentRoadmap.modules.length}</p>
          </div>

          <div className="space-y-4">
            {currentRoadmap.modules.map((mod, idx) => {
              const progress = studentProgress.find(p => p.moduleId === mod.id);
              const isLocked = progress?.status === 'LOCKED';
              const isActive = activeModuleId === mod.id;

              return (
                <button
                  key={mod.id}
                  disabled={isLocked}
                  onClick={() => setActiveModuleId(mod.id)}
                  className={`w-full p-6 text-left rounded-3xl transition-all border group relative ${
                    isActive ? 'bg-blue-600/10 border-blue-500/50 shadow-2xl shadow-blue-500/10' : 
                    isLocked ? 'opacity-30 cursor-not-allowed border-white/5 bg-transparent' : 'bg-white/5 border-white/5 hover:border-white/20 hover:bg-white/[0.02]'
                  }`}
                >
                  <div className="space-y-4">
                    <div className="flex items-center justify-between">
                      <span className={`text-[8px] font-black uppercase tracking-widest ${isActive ? 'text-blue-500' : 'text-slate-500'}`}>Node 0{idx+1}</span>
                      {progress?.status === 'COMPLETED' ? <CheckCircle2 className="w-4 h-4 text-emerald-500" /> : 
                       isLocked ? <Target className="w-3 h-3 text-slate-700" /> : <Wind className="w-3 h-3 text-blue-500" />}
                    </div>
                    <h4 className={`text-xs font-bold leading-snug ${isActive ? 'text-white' : 'text-slate-300'}`}>{mod.title}</h4>
                  </div>
                  {isActive && (
                    <motion.div 
                      layoutId="sidebar-active"
                      className="absolute -left-[1px] top-6 bottom-6 w-[2px] bg-blue-500 rounded-full"
                    />
                  )}
                </button>
              );
            })}
          </div>
        </aside>

        {/* Center Sandbox Area */}
        <main className="flex-1 flex flex-col bg-slate-950 relative overflow-hidden">
          <div className="h-16 border-b border-white/5 flex items-center justify-between px-10 bg-slate-950/50 relative z-10">
             <div className="flex items-center space-x-3 text-slate-400">
               <Terminal className="w-4 h-4" />
               <span className="text-[10px] font-black uppercase tracking-widest font-mono">Python Sandbox Engine v1.0.4</span>
             </div>
             <button 
               onClick={handleVerify}
               disabled={isVerifying || !activeModuleId}
               className="px-6 h-9 bg-blue-600 text-white rounded-full font-black text-[9px] uppercase tracking-widest hover:bg-blue-500 transition-all flex items-center space-x-2 shadow-lg shadow-blue-600/20"
             >
               {isVerifying ? <Loader2 className="w-3 h-3 animate-spin" /> : <ChevronRight className="w-3 h-3" />}
               <span>Verify Logic</span>
             </button>
          </div>

          <div className="flex-1 relative">
             <CodeEditor value={localCode} onChange={setLocalCode} />
             
             {/* Digital Twin Feedback Sidebar (Floating Right) */}
             <div className="absolute top-12 right-12 w-80 h-[480px] bg-slate-900/80 border border-white/10 rounded-[4rem] backdrop-blur-xl overflow-hidden shadow-2xl flex flex-col">
                <div className="h-16 border-b border-white/5 flex items-center px-8 justify-between shrink-0">
                   <div className="flex items-center space-x-3">
                      <Layers className="w-4 h-4 text-blue-500" />
                      <span className="text-[10px] font-black uppercase tracking-widest text-white">Digital Twin</span>
                   </div>
                   <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse" />
                </div>
                <div className="flex-1">
                   <DigitalTwin completionPercentage={completionPercentage} />
                </div>
             </div>
          </div>
        </main>
      </div>

      {/* Final Merge Modal */}
      <AnimatePresence>
        {showMerge && (
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-[100] bg-slate-950/90 backdrop-blur-xl flex items-center justify-center p-8 lg:p-24"
          >
            <motion.div 
              initial={{ scale: 0.9, y: 20 }}
              animate={{ scale: 1, y: 0 }}
              className="w-full h-full max-w-6xl bg-slate-900 border border-white/10 rounded-[4rem] shadow-2xl overflow-hidden flex flex-col shadow-blue-500/10"
            >
              <div className="h-24 border-b border-white/5 px-16 flex items-center justify-between shrink-0 bg-slate-950/50">
                <div className="space-y-1">
                  <h3 className="text-3xl font-black uppercase italic tracking-tighter leading-none">Final <span className="text-blue-500">Merge.</span></h3>
                  <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Consolidated SDG Logic Artifact</p>
                </div>
                <button 
                  onClick={() => setShowMerge(false)}
                  className="w-12 h-12 rounded-full bg-slate-950 border border-white/5 flex items-center justify-center hover:bg-white hover:text-slate-950 transition-all group"
                >
                  <Sparkles className="w-5 h-5 group-hover:scale-110 transition-transform" />
                </button>
              </div>
              <div className="flex-1 p-16 overflow-y-auto bg-slate-950/30">
                <div className="p-12 bg-slate-950 border border-white/5 rounded-[3rem] shadow-inner relative">
                  <pre className="text-xs font-mono text-slate-400 leading-relaxed selection:bg-blue-500/30">
                    {MergeManager.mergeImpactArtifact(currentRoadmap, studentProgress)}
                  </pre>
                  <div className="absolute top-8 right-8 px-4 py-2 bg-emerald-500/10 border border-emerald-500/20 rounded-full">
                     <span className="text-[8px] font-black uppercase tracking-widest text-emerald-500">Impact Verified</span>
                  </div>
                </div>
              </div>
              <div className="h-24 border-t border-white/5 px-16 flex items-center justify-between shrink-0 bg-slate-950/50">
                <div className="flex items-center space-x-6 text-[10px] font-black uppercase tracking-widest text-slate-500">
                   <div className="flex items-center space-x-2">
                      <div className="w-2 h-2 bg-emerald-500 rounded-full" />
                      <span>Logic Verified</span>
                   </div>
                   <div className="flex items-center space-x-2">
                      <div className="w-2 h-2 bg-blue-500 rounded-full" />
                      <span>Ready for Impact</span>
                   </div>
                </div>
                <button 
                  className="px-10 h-12 bg-white text-slate-950 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-emerald-400 transition-all shadow-xl shadow-white/10"
                >
                  Publish to Impact Ledger
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

import Link from 'next/link';
